<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$rows=db()->query('SELECT s.*,u.full_name FROM sales s JOIN users u ON u.id=s.cashier_id ORDER BY s.id DESC LIMIT 300')->fetchAll();$pageTitle='Sales History';require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><div><h2>Sales history</h2><p class="muted">Recent transactions and receipts</p></div><a class="btn primary" href="pos.php">＋ New sale</a></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Date & time</th><th>Cashier</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['receipt_number'])?></b></td><td><?=date('d M Y, H:i',strtotime($r['created_at']))?></td><td><?=e($r['full_name'])?></td><td><span class="status <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><b><?=money($r['total'])?></b></td><td><a class="text-link" href="receipt.php?id=<?=$r['id']?>">Receipt</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No sales have been recorded.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
